# Rebuilt 2026-09-14 against tuned225 matrix; source: /home/gaga/huzhan/MSI_ALL_aligned_11samples_consensus0.1Da/spatial_metabolite_modules_10samples/5A_step2_spatial_consensus.R
# 5A Step 2: within-sample block correlations, cross-sample consensus, conservative ion-family collapse
local({
suppressPackageStartupMessages({library(data.table);library(matrixStats);library(igraph);library(ggplot2);library(patchwork)})
BASE<-'/home/gaga/huzhan/MSI_ALL_aligned_10samples_consensus_tuned225'; OUT<-file.path(BASE,'spatial_metabolite_modules_10samples_tuned225'); S2<-file.path(OUT,'step2_spatial_consensus'); dir.create(file.path(S2,'sample_correlations'),recursive=TRUE,showWarnings=FALSE)
feat<-fread(file.path(OUT,'step1_feature_universe','eligible_876_MSI_features.csv')); fi<-feat$feature_index; p<-length(fi)
mask0<-readRDS(file.path(BASE,'intratumor_spatial_heterogeneity_10samples_part1_consensus_tuned225','tumor_pixels_within_sample_consensus_domains.rds'))
keepcols<-c('original_pixel_row','sample_id','diagnosis','source_id','x','y','raw_tic','detected_peak_count','alignment_nmatch')
meta<-as.data.table(mask0)[, ..keepcols]; meta[,sample_id:=as.character(sample_id)]; meta[,source_id:=as.character(source_id)]; setorder(meta,original_pixel_row)
stopifnot(uniqueN(meta$sample_id)==10L,!('Cushing-3'%in%meta$sample_id),!anyDuplicated(meta$original_pixel_row))
Xall<-readRDS(file.path(BASE,'pixel_by_feature_matrix_aligned_logCPM.rds')); stopifnot(nrow(Xall)>=max(meta$original_pixel_row),ncol(Xall)>=max(fi)); X<-as.matrix(Xall[meta$original_pixel_row,fi,drop=FALSE]); rm(Xall,mask0);gc()
safez<-function(v){s<-sd(v,na.rm=TRUE);if(!is.finite(s)||s<1e-10)return(rep(0,length(v)));as.numeric(scale(v))}
samples<-sort(unique(meta$sample_id)); arr<-array(NA_real_,dim=c(p,p,length(samples)),dimnames=list(as.character(fi),as.character(fi),samples)); blockstats<-list()
for(si in seq_along(samples)){s<-samples[si];ii<-which(meta$sample_id==s);md<-copy(meta[ii]);Y<-X[ii,,drop=FALSE];D<-cbind(1,safez(log1p(md$raw_tic)),safez(md$detected_peak_count),safez(md$alignment_nmatch));R<-qr.resid(qr(D),Y);md[,bx:=floor((x-min(x))/10),by=source_id];md[,by:=floor((y-min(y))/10),by=source_id];key<-paste(md$source_id,md$bx,md$by,sep='::');lev<-unique(key);g<-match(key,lev);B<-rowsum(R,g,reorder=FALSE)/as.numeric(tabulate(g));det<-colMeans(Y>0);ev<-det>=.05 & apply(B,2,sd)>1e-8;C<-suppressWarnings(cor(B,method='spearman',use='pairwise.complete.obs'));C[!ev,]<-NA_real_;C[,!ev]<-NA_real_;diag(C)[ev]<-1;arr[,,si]<-C;md[,block_key:=key];bmeta<-md[,.(source_id=first(source_id),bx=first(bx),by=first(by),n_pixels=.N),by=block_key];saveRDS(list(sample=s,feature_index=fi,block_matrix=B,block_metadata=bmeta,detection_fraction=det,evaluable=ev,spearman=C,technical_design_columns=c('intercept','log1p_raw_tic_z','detected_peak_count_z','alignment_nmatch_z')),file.path(S2,'sample_correlations',paste0(gsub('[^A-Za-z0-9]+','_',s),'_block10.rds')));blockstats[[si]]<-data.table(sample=s,n_tumor_pixels=length(ii),n_blocks=nrow(B),n_evaluable_features=sum(ev),median_detection=median(det),median_abs_raw_vs_residual_technical_cor=median(abs(cor(R,D[,-1,drop=FALSE])),na.rm=TRUE));cat('STEP2_SAMPLE',s,'pixels',length(ii),'blocks',nrow(B),'evaluable',sum(ev),'\n')}
M<-matrix(arr,nrow=p*p,ncol=length(samples));medv<-rowMedians(M,na.rm=TRUE);nev<-rowCounts(is.finite(M));posv<-rowMeans2(M>0,na.rm=TRUE);medv[nev==0]<-NA_real_;posv[nev==0]<-NA_real_;Cmed<-matrix(medv,p,p,dimnames=list(as.character(fi),as.character(fi)));Nmat<-matrix(nev,p,p);Ppos<-matrix(posv,p,p)
z<-which(upper.tri(Cmed),arr.ind=TRUE);edges<-data.table(feature_i=fi[z[,1]],feature_j=fi[z[,2]],median_spearman=Cmed[z],positive_fraction=Ppos[z],n_evaluable_samples=Nmat[z]);fwrite(edges,file.path(S2,'all_consensus_feature_pairs.csv'))
cand<-fread(file.path(OUT,'step1_feature_universe','mass_relation_candidate_pairs_before_spatial_check.csv'));mi<-match(cand$feature_i,fi);mj<-match(cand$feature_j,fi);cand[,median_spearman:=Cmed[cbind(mi,mj)]];cand[,positive_fraction:=Ppos[cbind(mi,mj)]];cand[,n_evaluable_samples:=Nmat[cbind(mi,mj)]];cand[,collapse_edge:=is.finite(median_spearman)&median_spearman>=.90&positive_fraction>=.80&n_evaluable_samples>=6L];fwrite(cand,file.path(S2,'mass_relation_candidates_with_spatial_validation.csv'))
ce<-unique(cand[collapse_edge==TRUE,.(from=as.character(feature_i),to=as.character(feature_j))]);gion<-graph_from_data_frame(ce,directed=FALSE,vertices=data.frame(name=as.character(fi)));membership<-components(gion)$membership[as.character(fi)];map<-copy(feat);map[,ion_family_component:=as.integer(membership)];setorder(map,ion_family_component,-n_samples_prevalent,median_abs_detection_qc_correlation,-median_logCPM_variance,feature_index);map[,representative_feature:=first(feature_index),by=ion_family_component];map[,is_representative:=feature_index==representative_feature];map[,ion_family_size:=.N,by=ion_family_component];setorder(map,feature_index);fwrite(map,file.path(S2,'ion_family_collapse_map.csv'));reps<-map[is_representative==TRUE];fwrite(reps,file.path(S2,'representative_features_for_module_detection.csv'))
bs<-rbindlist(blockstats);fwrite(bs,file.path(S2,'sample_block_summary.csv'));sumtab<-rbindlist(list(data.table(metric=c('eligible_input_features','mass_relation_candidates','spatially_validated_collapse_edges','ion_family_components','representative_features','features_removed_as_redundant_ions','largest_ion_family'),value=c(p,nrow(cand),nrow(ce),uniqueN(map$ion_family_component),nrow(reps),p-nrow(reps),max(map$ion_family_size))),bs[,.(metric=paste0('blocks_',sample),value=n_blocks)]));fwrite(sumtab,file.path(S2,'step2_summary.csv'))
p1<-ggplot(bs,aes(x=reorder(sample,n_blocks),y=n_blocks))+geom_col(fill='#2A6FBB')+coord_flip()+labs(x=NULL,y='10x10 spatial blocks',title='Per-sample block support')+theme_bw(base_size=11)
p2<-ggplot(edges[n_evaluable_samples>=8],aes(median_spearman))+geom_histogram(binwidth=.025,fill='#5A8F29',color='white')+geom_vline(xintercept=0,lty=2)+labs(x='Cross-sample median Spearman correlation',y='Feature-pair count',title='MSI spatial consensus')+theme_bw(base_size=11)
ggsave(file.path(S2,'step2_spatial_consensus.pdf'),p1/p2,width=9,height=7)
saveRDS(list(feature_index=fi,samples=samples,median_spearman=Cmed,positive_fraction=Ppos,n_evaluable_samples=Nmat,ion_family_map=map,parameters=list(block_width=10,correlation='Spearman on technical-residualized block means',evaluable='pixel detection >=5% and nonzero block variance',collapse='expected mass difference AND median rho>=0.90 AND positive in >=80% AND evaluable in >=6 physical samples',domain_labels_used=FALSE,LCMS_used=FALSE),session_info=sessionInfo()),file.path(S2,'spatial_consensus_and_ion_families.rds'))
writeLines(c('Discovery is MSI-only. The 1A file supplies only the upstream tumor-pixel mask and coordinates; all domain columns are discarded before matrix construction.','Correlations are estimated separately in each physical sample on 10x10 spatial block means after regression of raw TIC, detected peak count, and alignment match count.','Consensus is the median across physical samples with direction consistency and evaluable-sample counts. No pixels are pooled across patients.','Ion families are collapsed only when an expected mass difference and very high recurrent spatial concordance both hold.','LC-MS/MS is not read.'),file.path(S2,'README.txt'))
cat('STEP2_COMPLETE\n');print(sumtab);cat('OUT=',S2,'\n');rm(X,arr,M);gc()
})
